export interface Vec2 {
  x: number;
  y: number;
}

export interface Body {
  mass: number;
  position: Vec2;
  velocity: Vec2;
}

/** Unit normal pointing from A toward B, plus penetration depth. */
export interface Contact {
  normal: Vec2; // normalized
  penetration: number;
}

function dot(a: Vec2, b: Vec2): number {
  return a.x * b.x + a.y * b.y;
}

/**
 * Detect a circle-circle overlap between bodies whose `position` is the
 * circle center and which carry a `radius` property.
 */
export function collide(
  a: Body & { radius: number },
  b: Body & { radius: number }
): Contact | null {
  const dx = b.position.x - a.position.x;
  const dy = b.position.y - a.position.y;
  const distSq = dx * dx + dy * dy;
  const rSum = a.radius + b.radius;
  if (distSq >= rSum * rSum) return null;
  const dist = Math.sqrt(distSq);
  if (dist === 0) {
    // Degenerate: coincident centers; pick arbitrary axis.
    return { normal: { x: 1, y: 0 }, penetration: rSum };
  }
  return { normal: { x: dx / dist, y: dy / dist }, penetration: rSum - dist };
}

/**
 * Apply an impulse to resolve two touching circles.
 * j = -(1 + e) * velAlongNormal / (1/mA + 1/mB)
 * Returns the impulse magnitude (0 if the bodies are separating).
 */
export function resolve(a: Body, b: Body, contact: Contact, e: number): number {
  const rvx = b.velocity.x - a.velocity.x;
  const rvy = b.velocity.y - a.velocity.y;
  const velAlongNormal = rvx * contact.normal.x + rvy * contact.normal.y;

  // Separating: no impulse.
  if (velAlongNormal > 0) return 0;

  const invMassA = 1 / a.mass;
  const invMassB = 1 / b.mass;
  const j = (-(1 + e) * velAlongNormal) / (invMassA + invMassB);

  const ix = j * contact.normal.x;
  const iy = j * contact.normal.y;
  a.velocity.x -= invMassA * ix;
  a.velocity.y -= invMassA * iy;
  b.velocity.x += invMassB * ix;
  b.velocity.y += invMassB * iy;

  return j;
}

