import { describe, it, expect } from "vitest";
import { Body, Contact, resolve, momentum } from "./physics";

function makeBody(mass: number, vx: number, vy: number): Body {
  return {
    mass,
    position: { x: 0, y: 0 },
    velocity: { x: vx, y: vy },
  };
}

// Head-on along +x: normal from A to B is (1, 0).
const headOn: Contact = { normal: { x: 1, y: 0 }, penetration: 0 };

function momentumOf(b: Body): number {
  return b.mass * b.velocity.x + b.mass * b.velocity.y;
}

describe("circle-circle impulse resolution", () => {
  it("equal masses head-on with e=1 exactly swap velocities", () => {
    const a = makeBody(2, 5, 0);
    const b = makeBody(2, -3, 0);
    resolve(a, b, headOn, 1);
    expect(a.velocity.x).toBeCloseTo(-3, 12);
    expect(a.velocity.y).toBeCloseTo(0, 12);
    expect(b.velocity.x).toBeCloseTo(5, 12);
    expect(b.velocity.y).toBeCloseTo(0, 12);
  });

  it("e=0 head-on leaves both moving at the common velocity", () => {
    const a = makeBody(3, 6, 0);
    const b = makeBody(1, -2, 0);
    resolve(a, b, headOn, 0);
    // v = (m1*v1 + m2*v2) / (m1+m2) = (18 - 2)/4 = 4
    const expected = (3 * 6 + 1 * -2) / (3 + 1);
    expect(a.velocity.x).toBeCloseTo(expected, 12);
    expect(b.velocity.x).toBeCloseTo(expected, 12);
  });

  it("conserves total momentum for equal-mass e=1 collision", () => {
    const before = momentumOf(makeBody(2, 5, 0)) + momentumOf(makeBody(2, -3, 0));
    const a = makeBody(2, 5, 0);
    const b = makeBody(2, -3, 0);
    resolve(a, b, headOn, 1);
    expect(before).toBeCloseTo(momentumOf(a) + momentumOf(b), 9);
  });

  it("conserves total momentum for unequal masses e=0", () => {
    const before = momentumOf(makeBody(3, 6, 0)) + momentumOf(makeBody(1, -2, 0));
    const a = makeBody(3, 6, 0);
    const b = makeBody(1, -2, 0);
    resolve(a, b, headOn, 0);
    expect(before).toBeCloseTo(momentumOf(a) + momentumOf(b), 9);
  });

  it("conserves total momentum for arbitrary masses, angle and restitution", () => {
    const contact: Contact = { normal: { x: 0.6, y: 0.8 }, penetration: 0.1 };
    const a = makeBody(1.7, 2.5, -1.25);
    const b = makeBody(4.3, -0.75, 0.5);
    const px = a.mass * a.velocity.x + b.mass * b.velocity.x;
    const py = a.mass * a.velocity.y + b.mass * b.velocity.y;
    resolve(a, b, contact, 0.65);
    expect(px).toBeCloseTo(a.mass * a.velocity.x + b.mass * b.velocity.x, 9);
    expect(py).toBeCloseTo(a.mass * a.velocity.y + b.mass * b.velocity.y, 9);
  });

  it("separating bodies receive zero impulse", () => {
    const a = makeBody(2, -1, 0); // moving away from B
    const b = makeBody(2, 3, 0); // relative velocity +4 along normal
    const j = resolve(a, b, headOn, 1);
    expect(j).toBe(0);
    expect(a.velocity.x).toBe(-1);
    expect(b.velocity.x).toBe(3);
  });
});

